fn main() -> Int {
  let original = Vec[Int]();
  original.push(1);
  original.push(2);
  original.push(3);
  original.push(4);
  original.push(5);

  var clone = original.clone();
  clone.push(6);

  var sum_orig = 0;
  var i = 0;
  while i < original.len() {
    sum_orig = sum_orig + original[i];
    i = i + 1;
  }

  var sum_clone = 0;
  i = 0;
  while i < clone.len() {
    sum_clone = sum_clone + clone[i];
    i = i + 1;
  }

  return sum_orig + sum_clone;
}
